"""Scaffold guards: names, registration into hand-edited files, generated files.

Each test reproduces a break-it round 2 finding (R2-037 … R2-109) on a project
generated by this checkout's scaffold.
"""
import ast
import contextlib
import os
import re
import stat
import subprocess
import sys
import tempfile
import tomllib
import unittest
from pathlib import Path
from unittest import mock

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from dlux.scaffold import ScaffoldError, create_app, create_project, split_image_reference

REPO_ROOT = Path(__file__).resolve().parents[2]


@contextlib.contextmanager
def _cwd(path):
    previous = Path.cwd()
    os.chdir(path)
    try:
        yield
    finally:
        os.chdir(previous)


def _project(tmp, name="demo"):
    return create_project(name, Path(tmp) / name, image="example/app", repo="", interactive=False)


def _snapshot(root):
    return sorted(str(path.relative_to(root)) for path in root.rglob("*"))


class GeneratedProjectFileTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls._tmp = tempfile.TemporaryDirectory()
        cls.root = _project(cls._tmp.name)

    @classmethod
    def tearDownClass(cls):
        cls._tmp.cleanup()

    def read(self, name):
        return (self.root / name).read_text(encoding="utf-8")

    def test_requirements_install_the_pdf_extra_document_files_need(self):
        # R2-037: every document-file save reads the PDF with pypdf.
        line = self.read("requirements.txt").splitlines()[0]
        extras = re.match(r"django-lux\[([^\]]+)\]==", line).group(1).split(",")
        self.assertIn("pdf", extras)
        self.assertIn("ocr", extras)
        self.assertIn("updater", extras)

    def test_gunicorn_control_socket_is_disabled_and_gunicorn_pinned(self):
        # R2-107: gunicorn 27 opens a control socket under $HOME (/ as uid 10001).
        namespace = {}
        exec(compile(self.read("gunicorn.py"), "gunicorn.py", "exec"), namespace)
        self.assertIs(namespace.get("control_socket_disable"), True)
        gunicorn = [line for line in self.read("requirements.txt").splitlines() if line.startswith("gunicorn")]
        self.assertEqual(gunicorn, ["gunicorn>=27,<28"])

    def test_secrets_file_ends_with_a_newline(self):
        # R2-108: `echo KEY=value >> .secrets/.env` must start a new line.
        data = (self.root / ".secrets" / ".env").read_bytes()
        self.assertTrue(data.endswith(b"\n"))
        self.assertFalse(data.endswith(b"\n\n"))

    def test_admin_password_has_no_default(self):
        # R2-039: the first superuser got the password `admin` when ADMIN_PASS was unset.
        compose = self.read("compose.yml")
        self.assertNotIn("ADMIN_PASS:-admin", compose)
        self.assertEqual(compose.count("ADMIN_PASS: ${ADMIN_PASS:-}"), 2)
        values = dict(line.split("=", 1) for line in self.read(".secrets/.env").splitlines()
                      if line and not line.startswith("#"))
        self.assertEqual(values["ADMIN_PASS"], "")
        readme = self.read("README.md")
        self.assertIn("`./start.sh` asks for it at a terminal on the first start", readme)
        self.assertIn("no admin account is created until it is set", readme)

    def test_database_password_is_random_per_project(self):
        # Every new project shipped POSTGRES_PASSWORD=admin_pass.
        def env_value(root):
            for line in (root / ".secrets" / ".env").read_text(encoding="utf-8").splitlines():
                if line.startswith("POSTGRES_PASSWORD="):
                    return line.split("=", 1)[1]
            self.fail("POSTGRES_PASSWORD missing from .secrets/.env")

        with tempfile.TemporaryDirectory() as tmp:
            other = env_value(_project(tmp, "other"))
        first = env_value(self.root)
        self.assertNotEqual(first, other)
        for value in (first, other):
            self.assertNotEqual(value, "admin_pass")
            self.assertGreaterEqual(len(value), 32)
            # Safe in .env parsing, a Postgres URL and Compose interpolation.
            self.assertRegex(value, r"\A[A-Za-z0-9_-]+\Z")
        readme = self.read("README.md")
        self.assertIn("Change `POSTGRES_PASSWORD` only before the first start", readme)

    def test_secrets_file_is_owner_only(self):
        # R2-109: the file holds the database password and SECRET_KEY.
        mode = stat.S_IMODE((self.root / ".secrets" / ".env").stat().st_mode)
        self.assertEqual(mode, 0o600)

    def _settings_tree(self):
        return ast.parse(self.read("config/settings.py"))

    def _assigned(self, name):
        for node in self._settings_tree().body:
            if isinstance(node, ast.Assign) and any(getattr(t, "id", None) == name for t in node.targets):
                return node.value
        self.fail(f"settings.py assigns no {name}")

    def test_csp_sets_base_uri_and_object_src(self):
        # R2-093: no base-uri lets an injected <base> repoint nonce'd relative scripts.
        directives = {}
        policy = self._assigned("CONTENT_SECURITY_POLICY")
        for key, value in zip(policy.keys, policy.values):
            if key.value == "DIRECTIVES":
                directives = {k.value: [ast.unparse(item) for item in v.elts] for k, v in zip(value.keys, value.values)}
        self.assertEqual(directives.get("base-uri"), ["SELF"])
        self.assertEqual(directives.get("object-src"), ["NONE"])
        self.assertIn("from csp.constants import NONCE, NONE, SELF, UNSAFE_INLINE", self.read("config/settings.py"))
        from csp.constants import NONE

        self.assertEqual(NONE, "'none'")

    def test_logging_sends_request_errors_with_traceback_to_stderr(self):
        # R2-090: with DEBUG off, Django's default logging drops django.request errors.
        logging_config = ast.literal_eval(self._assigned("LOGGING"))
        script = (
            "import logging, logging.config, sys\n"
            f"logging.config.dictConfig({logging_config!r})\n"
            "try:\n"
            "    raise ModuleNotFoundError('pypdf probe')\n"
            "except Exception:\n"
            "    logging.getLogger('django.request').error('Internal Server Error: /x/', exc_info=True)\n"
            "logging.getLogger('django.request').warning('Not Found: /quiet/')\n"
            "logging.getLogger('dlux.files').warning('dlux warning probe')\n"
        )
        result = subprocess.run([sys.executable, "-c", script], capture_output=True, text=True, timeout=60)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("Internal Server Error: /x/", result.stderr)
        self.assertIn("ModuleNotFoundError: pypdf probe", result.stderr)
        self.assertIn("dlux warning probe", result.stderr)
        self.assertNotIn("Not Found: /quiet/", result.stderr)


class StartprojectNameTests(unittest.TestCase):
    # R2-104
    REFUSED = ["true", "True", "false", "FALSE", "null", "Null", "café", "日本", "_private", "__init__",
               "con", "NUL", "com1", "a" * 51, "a" * 300, "class"]

    def test_undeployable_names_are_refused_before_anything_is_written(self):
        for name in self.REFUSED:
            with self.subTest(name=name), tempfile.TemporaryDirectory() as tmp:
                with self.assertRaises(ScaffoldError):
                    create_project(name, None if len(name) > 200 else Path(tmp) / "p",
                                   image="example/app", repo="", interactive=False)
                self.assertEqual(_snapshot(Path(tmp)), [])

    def test_ordinary_names_still_work(self):
        for name in ("shop", "my-project", "Shop2", "a" * 50):
            with self.subTest(name=name), tempfile.TemporaryDirectory() as tmp:
                root = create_project(name, Path(tmp) / "p", image="example/app", repo="", interactive=False)
                self.assertTrue((root / "compose.yml").exists())

    def test_invalid_image_references_are_refused(self):
        for reference in ("UPPER/Case:tag", "img@sha256:abc", "img:tag:extra", "img;id", "img:-bad",
                          "img:t/ag", "img:", "-img", "img..x", "a" * 300, "img:" + "t" * 129,
                          "registry.example.com/Team/app", "reg:port/app"):
            with self.subTest(reference=reference):
                with self.assertRaises(ScaffoldError):
                    split_image_reference(reference)

    def test_valid_image_references_are_kept(self):
        cases = {
            "app": ("app", "latest"),
            "team/app:1.0": ("team/app", "1.0"),
            "reg:5000/team/app": ("reg:5000/team/app", "latest"),
            "registry.example.com/team-x/app_1:v1.2.3-rc.1": ("registry.example.com/team-x/app_1", "v1.2.3-rc.1"),
            "Registry.Example.com:5000/team/app:Dev": ("Registry.Example.com:5000/team/app", "Dev"),
            "localhost/app:Dev_1": ("localhost/app", "Dev_1"),
        }
        for reference, expected in cases.items():
            with self.subTest(reference=reference):
                self.assertEqual(split_image_reference(reference), expected)

    def test_operating_system_errors_become_scaffold_errors(self):
        with tempfile.TemporaryDirectory() as tmp:
            parent = Path(tmp) / "readonly"
            parent.mkdir()
            parent.chmod(0o555)
            try:
                with self.assertRaises(ScaffoldError) as caught:
                    create_project("shop", parent / "shop", image="example/app", repo="", interactive=False)
                self.assertIn("shop", str(caught.exception))
            finally:
                parent.chmod(0o755)


class StartappTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.root = _project(self._tmp.name)
        self.settings = self.root / "config" / "settings.py"
        self.urls = self.root / "config" / "urls.py"

    def tearDown(self):
        for path in self.root.rglob("*"):
            with contextlib.suppress(OSError):
                path.chmod(0o755 if path.is_dir() else 0o644)
        self._tmp.cleanup()

    def startapp(self, name, register=True):
        with _cwd(self.root):
            return create_app(name, register=register)

    def test_every_template_a_generated_view_names_is_written(self):
        # R2-040: the detail and delete views named templates startapp never wrote.
        app_root = self.startapp("vault")
        views = (app_root / "views.py").read_text(encoding="utf-8")
        names = re.findall(r'template_name = "([^"]+)"', views)
        self.assertGreaterEqual(len(names), 4)
        for name in names:
            with self.subTest(template=name):
                self.assertTrue((app_root / "templates" / name).is_file())

    def test_generated_templates_show_only_translated_text(self):
        # Every word a generated page shows comes from DLUX_STRINGS, in English and Arabic.
        from dlux.translations.strings import ARABIC, ENGLISH

        app_root = self.startapp("vault")
        namespace = {}
        exec((app_root / "translations.py").read_text(encoding="utf-8"), namespace)
        app_strings = namespace["DLUX_STRINGS"]
        self.assertEqual(set(app_strings["en"]), set(app_strings["ar"]))
        templates = sorted((app_root / "templates" / "vault").glob("*.html"))
        self.assertEqual(len(templates), 4)
        for template in templates:
            with self.subTest(template=template.name):
                source = template.read_text(encoding="utf-8")
                visible = re.sub(r"{%.*?%}|{{.*?}}|<[^>]*>", " ", source, flags=re.DOTALL)
                self.assertEqual(visible.split(), [], "text outside DLUX_STRINGS lookups")
                for attribute in re.findall(r'(?:title|placeholder|aria-label)="([^"]*)"', source):
                    self.assertRegex(attribute.strip(), r"^{{ DLUX_STRINGS\.")
                keys = re.findall(r"DLUX_STRINGS\.(\w+)\|default:", source)
                self.assertTrue(keys)
                for key in keys:
                    for language, core in (("en", ENGLISH), ("ar", ARABIC)):
                        self.assertTrue(key in app_strings[language] or key in core, f"{key} ({language})")
                self.assertEqual(len(keys), source.count("DLUX_STRINGS."), "every lookup has a default")

    def test_two_registered_apps_pass_djangos_checks(self):
        # R2-050: identical example model names clashed on Scope's reverse accessors.
        self.startapp("foo")
        self.startapp("bar")
        script = (
            "import sys\n"
            f"sys.path.insert(0, {str(self.root)!r})\n"
            f"sys.path.insert(1, {str(REPO_ROOT)!r})\n"
            "from django.conf import settings\n"
            "import dlux.tests.settings as base\n"
            "values = {k: getattr(base, k) for k in dir(base) if k.isupper()}\n"
            "values['INSTALLED_APPS'] = list(values['INSTALLED_APPS']) + ['foo', 'bar']\n"
            "settings.configure(**values)\n"
            "import django\n"
            "django.setup()\n"
            "from django.core import checks\n"
            "errors = [m for m in checks.run_checks() if m.is_serious()]\n"
            "print('\\n'.join(f'{m.id} {m.msg}' for m in errors))\n"
            "sys.exit(1 if errors else 0)\n"
        )
        env = {**os.environ}
        env.pop("DJANGO_SETTINGS_MODULE", None)
        result = subprocess.run([sys.executable, "-c", script], capture_output=True, text=True,
                                timeout=180, cwd=self.root, env=env)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_names_that_shadow_modules_or_labels_are_refused(self):
        # R2-105
        before = _snapshot(self.root)
        settings_before = self.settings.read_bytes()
        for name in ("json", "logging", "email", "typing", "django", "dlux", "csp", "os", "site", "test",
                     "auth", "sessions", "staticfiles", "admin", "contenttypes", "health_check",
                     "corsheaders", "class", "__init__", "_private", "café", "config"):
            with self.subTest(name=name):
                with self.assertRaises(ScaffoldError):
                    self.startapp(name)
        self.assertEqual(_snapshot(self.root), before)
        self.assertEqual(self.settings.read_bytes(), settings_before)

    def test_crlf_files_keep_their_line_endings(self):
        # R2-106
        for path in (self.settings, self.urls):
            path.write_bytes(path.read_bytes().replace(b"\n", b"\r\n"))
        self.startapp("foo")
        for path in (self.settings, self.urls):
            data = path.read_bytes()
            self.assertEqual(data.count(b"\n"), data.count(b"\r\n"), path.name)
            ast.parse(data.decode("utf-8"))
        self.assertIn(b'"foo",\r\n', self.settings.read_bytes())

    def test_multiline_url_import_stays_valid_python(self):
        # R2-106
        source = self.urls.read_text(encoding="utf-8")
        source = re.sub(r"^from django\.urls import [^\n]+$", "from django.urls import (\n    path,\n)",
                        source, count=1, flags=re.MULTILINE)
        self.urls.write_text(source, encoding="utf-8")
        self.startapp("foo")
        tree = ast.parse(self.urls.read_text(encoding="utf-8"))
        imported = {alias.name for node in tree.body if isinstance(node, ast.ImportFrom)
                    and node.module == "django.urls" for alias in node.names}
        self.assertLessEqual({"include", "path"}, imported)

    def test_a_docstring_mentioning_installed_apps_is_left_alone(self):
        # R2-106
        source = self.settings.read_text(encoding="utf-8")
        decoy = '"""Example:\n\nINSTALLED_APPS = [\n]\n"""\n'
        self.settings.write_text(decoy + source, encoding="utf-8")
        self.startapp("foo")
        tree = ast.parse(self.settings.read_text(encoding="utf-8"))
        self.assertEqual(ast.get_docstring(tree, clean=False), "Example:\n\nINSTALLED_APPS = [\n]\n")
        installed = next(node.value for node in tree.body if isinstance(node, ast.Assign)
                         and getattr(node.targets[0], "id", None) == "INSTALLED_APPS")
        self.assertIn("foo", [elt.value for elt in installed.elts])

    def _assert_refused_untouched(self, name="foo"):
        settings_before, urls_before = self.settings.read_bytes(), self.urls.read_bytes()
        with self.assertRaises(ScaffoldError):
            self.startapp(name)
        self.assertFalse((self.root / name).exists(), "no app files before registration is known to work")
        self.assertEqual(self.settings.read_bytes(), settings_before)
        self.assertEqual(self.urls.read_bytes(), urls_before)

    def test_a_tuple_installed_apps_is_refused_before_any_file_is_written(self):
        # R2-106
        source = self.settings.read_text(encoding="utf-8")
        start = source.index("INSTALLED_APPS = [")
        end = source.index("\n]\n", start)
        self.settings.write_text(source[:start] + "INSTALLED_APPS = (" + source[start + 18:end] + "\n)\n"
                                 + source[end + 3:], encoding="utf-8")
        self._assert_refused_untouched()

    def test_a_read_only_urls_file_is_refused_before_any_file_is_written(self):
        # R2-106
        self.urls.chmod(0o444)
        self._assert_refused_untouched()

    def test_a_removed_end_marker_is_refused(self):
        # R2-106
        self.startapp("foo")
        source = self.settings.read_text(encoding="utf-8")
        self.settings.write_text(source.replace("    # DjangoLux generated apps end\n", ""), encoding="utf-8")
        self._assert_refused_untouched("bar")

    def test_registration_is_idempotent_and_ordered(self):
        self.startapp("foo")
        self.startapp("bar")
        settings = self.settings.read_text(encoding="utf-8")
        block = settings.split("# DjangoLux generated apps start", 1)[1].split("# DjangoLux generated apps end", 1)[0]
        self.assertEqual([line.strip() for line in block.strip().splitlines()], ['"foo",', '"bar",'])
        urls = self.urls.read_text(encoding="utf-8")
        self.assertEqual(urls.count('namespace="foo"'), 1)
        self.assertEqual(urls.count('namespace="bar"'), 1)


class OcrPackagingTests(unittest.TestCase):
    """R2-038: every ``ocr`` pin must have a wheel on each supported Python."""

    def test_the_ocr_numpy_pin_supports_python_3_11(self):
        from packaging.requirements import Requirement
        from packaging.version import Version

        project = tomllib.loads((REPO_ROOT / "pyproject.toml").read_text(encoding="utf-8"))["project"]
        self.assertEqual(project["requires-python"], ">=3.11")
        numpy = [Requirement(item) for item in project["optional-dependencies"]["ocr"] if item.startswith("numpy")]
        for python in ("3.11", "3.12", "3.13", "3.14"):
            with self.subTest(python=python):
                env = {"python_version": python, "python_full_version": f"{python}.0", "extra": "ocr"}
                chosen = [req for req in numpy if req.marker is None or req.marker.evaluate(env)]
                self.assertEqual(len(chosen), 1, chosen)
                pinned = Version(next(iter(chosen[0].specifier)).version)
                if python == "3.11":
                    # numpy 2.5 publishes no cp311 wheels.
                    self.assertLess(pinned, Version("2.5"))


class DocumentFilesNeedPypdfCheckTests(unittest.TestCase):
    """R2-037: a registered document file without pypdf is reported by ``check``."""

    @classmethod
    def setUpClass(cls):
        os.environ.setdefault("DJANGO_SETTINGS_MODULE", "dlux.tests.settings")
        import django

        django.setup()

    def setUp(self):
        from dlux.files.registry import register_document_file, unregister_document_file
        from dlux.tests.document_files_app.models import Paper

        register_document_file(Paper, "pdf_file")
        self.addCleanup(unregister_document_file, Paper, "pdf_file")

    def test_warns_when_pypdf_is_missing(self):
        from dlux.files.checks import check_document_files_have_pypdf

        with mock.patch("dlux.files.checks.find_spec", return_value=None):
            messages = check_document_files_have_pypdf()
        self.assertEqual([m.id for m in messages], ["dlux.W103"])
        self.assertIn("document_files_app.Paper.pdf_file", messages[0].msg)
        self.assertIn("django-lux[pdf]", messages[0].hint)

    def test_the_check_is_registered_with_django(self):
        from django.core import checks

        with mock.patch("dlux.files.checks.find_spec", return_value=None):
            ids = [message.id for message in checks.run_checks()]
        self.assertIn("dlux.W103", ids)

    def test_silent_when_pypdf_is_installed_or_nothing_is_registered(self):
        from dlux.files import checks

        self.assertEqual(checks.check_document_files_have_pypdf(), [])
        with mock.patch.object(checks, "registered_document_files", return_value=[]), \
                mock.patch.object(checks, "find_spec", return_value=None):
            self.assertEqual(checks.check_document_files_have_pypdf(), [])


if __name__ == "__main__":
    unittest.main()
